import{_ as o,l as s,o as e,c as l,v as t,p as i,x as n,d as E,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"Johansen","description":"","frontmatter":{"title":"Johansen","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/johansen.md","filePath":"quant/johansen.md","lastUpdated":1789023840000}'),_={name:"quant/johansen.md"};function d(m,a,A,B,c,u){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="johansen" tabindex="-1">Johansen <a class="header-anchor" href="#johansen" aria-label="Permalink to &quot;Johansen&quot;">​</a></h1><div class="epigraph"><p>把水平项的系数矩阵写成调整速度与协整向量的乘积，矩阵的秩就是协整关系的个数；迹检验与最大特征值检验在高斯向量自回归里对此秩做似然比。</p><footer>—— Johansen, Statistical Analysis of Cointegration Vectors, Journal of Economic Dynamics and Control 1988；高斯 VAR 上的估计与检验见 Johansen, Econometrica 1991</footer></div><p>两只腿的配对可以用 <a href="/quant/engle-granger">Engle–Granger</a> 一条回归打发。三只以上、或要同时问「有几条独立的长期关系」，两步法不够：协整向量张成一个空间，规范化与约束必须在系统里做。Johansen 把向量误差修正模型（VECM）里水平项的系数矩阵 \\(\\Pi\\) 写成 \\(\\alpha\\beta&#39;\\)，对 \\(\\Pi\\) 的秩做极大似然。秩为 \\(r\\) 表示 \\(r\\) 条协整关系。篮子交易、期现加利率、多空一组相关股，问的都是这个秩，以及 \\(\\beta\\) 能不能被经济约束识别。本篇写迹检验与最大特征值、确定性项如何改渐近，以及秩估对了并不等于每条价差都可交易。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设 \\(X_t\\) 为 \\(p\\) 维 \\(I(1)\\) 向量。VAR 写成 VECM</p> \\[\\Delta X_t=\\Pi X_{t-1}+\\sum_{i=1}^{k-1}\\Gamma_i\\Delta X_{t-i}+\\Phi D_t+\\varepsilon_t, \\]<p>\\(\\varepsilon_t\\) 高斯白噪声。若 \\(X\\) 协整，则 \\(\\Pi\\) 不满秩，\\(\\Pi=\\alpha\\beta&#39;\\)，\\(\\beta\\) 是 \\(p\\times r\\) 的协整矩阵，\\(\\alpha\\) 是调整载荷。\\(r=0\\) 表示无协整，应在差分上做 VAR；\\(r=p\\) 表示 \\(X\\) 已是 \\(I(0)\\)，不该当 \\(I(1)\\) 系统。问题是估计 \\(r\\)，并在给定 \\(r\\) 下估 \\(\\beta\\) 的空间。</p><p>Engle–Granger 只覆盖 \\(p=2,\\ r=1\\)，还要先选谁当左边。Johansen 一次性处理 \\(p\\gt 2\\) 与 \\(r\\gt 1\\)，并用似然比而不是残差 ADF。代价是：滞后阶、常数与趋势的放置、样本长度，都会改检验的尺寸。错的确定性项比错的临界值更常见。</p><h3 id="协整空间与识别" tabindex="-1">协整空间与识别 <a class="header-anchor" href="#协整空间与识别" aria-label="Permalink to &quot;协整空间与识别&quot;">​</a></h3><p>\\(\\beta\\) 只能识别到空间：\\(\\beta\\) 右乘任意可逆 \\(r\\times r\\) 矩阵，同一 \\(\\Pi\\)。要谈「第一条价差是 \\(X_1-\\beta_2 X_2\\)」，必须加规范化（某一行为 1）或经济约束（排除某个资产、齐次约束）。未约束的特征向量没有交易含义。Johansen–Juselius 的约束检验，问的是某组线性限制是否还在协整空间里，而不是软件输出的前 \\(r\\) 个向量能不能直接下单。</p><p><span class="marginnote">秩 \\(r=2\\) 意味着两条独立的平稳组合，不是「有两个好做的配对」。两条组合张成平面，其中大多数方向波动大、半衰期长。交易要在空间里再选一条（最小方差、最快回复、或与成本对齐的方向），那是识别与组合问题，不是迹检验的输出。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>特征根。</strong> 在高斯假设下，Johansen 把问题收成一次广义特征分解：先把 \\(\\Delta X_t\\) 与 \\(X_{t-1}\\) 对滞后差分和确定性项回归，得残差 \\(R_{0t}\\)、\\(R_{1t}\\)，再解</p> \\[|\\lambda S_{11}-S_{10}S_{00}^{-1}S_{01}|=0, \\]<p>特征根 \\(\\hat\\lambda_1\\ge\\cdots\\ge\\hat\\lambda_p\\)。\\(\\hat\\lambda_i\\) 大表示对应方向上水平项解释差分的能力强，像协整。极大似然协整向量是相应的广义特征向量。</p><p><strong>迹检验。</strong> \\(H_0:r\\le r_0\\) 对 \\(H_1:r\\gt r_0\\)，统计量 \\(-T\\sum_{i=r_0+1}^{p}\\ln(1-\\hat\\lambda_i)\\)。从 \\(r_0=0\\) 起顺序测，第一次不拒绝的 \\(r_0\\) 当作秩。</p><p><strong>最大特征值。</strong> \\(H_0:r=r_0\\) 对 \\(H_1:r=r_0+1\\)，统计量 \\(-T\\ln(1-\\hat\\lambda_{r_0+1})\\)。两种检验渐近不同，有限样本常打架。应预先规定顺序规则，不能看哪个显著就取哪个 \\(r\\)。</p><p>确定性项有五种常见放置（Johansen 的 Case 0–4）：无常数、限制在协整内的常数（价差有均值）、差分方程里的非限制常数（线性趋势）、趋势限制在协整内，等等。临界值随 case 变。价差若应在某个水平附近摆动，通常把常数限制在 \\(\\beta\\) 里，而不是让每条腿有独立漂移——独立漂移意味着价差可以有趋势，与均值回复交易冲突。</p><h3 id="滞后与小样本" tabindex="-1">滞后与小样本 <a class="header-anchor" href="#滞后与小样本" aria-label="Permalink to &quot;滞后与小样本&quot;">​</a></h3><p>\\(k\\) 太小，残差相关，检验过拒；\\(k\\) 太大，吃掉水平项的信息，功效差。信息准则选 \\(k\\) 是默认，但协整检验对 \\(k\\) 敏感，应报告邻近滞后。小样本可用 Bartlett 修正或 bootstrap。\\(p\\) 相对 \\(T\\) 大时特征根不可靠，先降维（指数、主成分）再 Johansen，或承认只能做低维篮子。</p><p>约束：例如三资产要求 \\(\\beta\\) 正交于 \\((1,1,1)\\)（市值中性篮子），用似然比在给定 \\(r\\) 下检验。拒绝意味着「中性组合不在协整空间」，不是「中性组合不能交易」——它可能仍有短暂均值回复，只是不是 \\(I(0)\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>高斯 VAR 的似然只通过残差的协方差与 \\(\\Pi\\) 的秩依赖数据。把 \\(\\Pi\\) 降秩，是把水平 \\(X_{t-1}\\) 投影到 \\(r\\) 维，让差分的条件均值活在这 \\(r\\) 个误差修正通道里。特征根衡量各通道的强度。迹把剩下所有可能的根加起来，问「还有没有协整」；最大特征值一次只加一根，问「要不要再多一条」。顺序检验控制的是这条链上的渐近水平，不是对「真实 \\(r\\)」的事后概率。</p><p>与 Engle–Granger 的机制对比：两步是先把 \\(\\beta\\) 用静态 OLS 钉死再问残差；Johansen 是在动态系统里同时估 \\(\\alpha\\) 与 \\(\\beta\\)，并利用全部方程的信息。\\(x\\) 若被 \\(\\alpha\\) 拉动（非弱外生），系统估计更有效；若你其实只关心一条回归，Engle–Granger 仍更透明。</p><p><span class="marginnote">软件打印的「协整方程 1、2」是规范化后的基，不是按可交易性排序。把第一向量当头号信号、第二当次号，是误读特征向量的排列。排列来自特征根大小，对应调整强度，不对应夏普。</span></p><h3 id="从秩到价差" tabindex="-1">从秩到价差 <a class="header-anchor" href="#从秩到价差" aria-label="Permalink to &quot;从秩到价差&quot;">​</a></h3><p>给定 \\(r\\) 与一组约束，得到 \\(\\hat\\beta&#39;X_t\\) 共 \\(r\\) 条残差序列。此后与两资产情形相同：每条残差去拟合 <a href="/quant/ou-spread">OU</a>，看<a href="/quant/half-life-bands">半衰期与阈值</a>，或用 <a href="/quant/kalman-hedge">Kalman</a> 让 \\(\\beta\\) 慢变——后者已经离开常系数 VECM。秩检验通过只说明样本内存在 \\(I(0)\\) 组合，不说明组合的波动覆盖成本，也不说明样本外 \\(\\Pi\\) 不变。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>高斯新息是似然的骨架；厚尾与<a href="/quant/jump-tests">跳跃</a>使检验过拒。可改准似然或对异常值稳健的 VECM，但临界值要重来。结构断裂使全样本秩不稳定：前半 \\(r=1\\)、后半 \\(r=0\\) 时，合并样本会给出难以解释的根。应做样本分割或带断裂的协整检验。</p><p>不要在未确定滞后与确定性项之前比较不同篮子的迹统计量。不要把 \\(p=10\\) 只股票直接 Johansen 再用 \\(r=3\\) 的三条腿同时开仓——估计误差与识别不足会主导。不要忽略 \\(\\alpha\\)：若某条价差的载荷接近 0，它在样本内像协整、在预测上几乎不回调。</p><p>与 Engle–Granger 的工程分工：探索性两资产、报告对冲比，用两步；要秩、要约束、要多腿，用 Johansen。两者都不是下单规则。指数套利还要处理新成分、停牌与不同步，那是数据问题，似然比解决不了。</p><p><span class="marginnote">Johansen（1991）的渐近是 \\(T\\to\\infty\\)、VAR 阶数正确、新息独立同分布高斯。日频金融很难同时满足。把 \\(p\\) 值当「这对篮子可以做市」是把检验当成了策略评价。</span></p>',32)),(e(),i(p,null,{default:n(()=>[h(r,{id:"mermaid-90",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22p%20%E7%BB%B4%20I(1)%20%E5%90%91%E9%87%8F%22%5D%20--%3E%20VECM%5B%22VECM%3A%20%CE%A0%20%3D%20%CE%B1%20%CE%B2'%22%5D%0A%20%20VECM%20--%3E%20DET%5B%22%E6%94%BE%E7%BD%AE%E5%B8%B8%E6%95%B0%20%2F%20%E8%B6%8B%E5%8A%BF%22%5D%0A%20%20VECM%20--%3E%20LAG%5B%22%E9%80%89%E6%8B%A9%E6%BB%9E%E5%90%8E%20k%22%5D%0A%20%20DET%20--%3E%20EIG%5B%22%E5%B9%BF%E4%B9%89%E7%89%B9%E5%BE%81%E6%A0%B9%20%CE%BB%22%5D%0A%20%20LAG%20--%3E%20EIG%0A%20%20EIG%20--%3E%20TR%5B%22%E8%BF%B9%E6%A3%80%E9%AA%8C%3A%20r%20%E2%89%A4%20r0%22%5D%0A%20%20EIG%20--%3E%20ME%5B%22%E6%9C%80%E5%A4%A7%E7%89%B9%E5%BE%81%E5%80%BC%3A%20r%20%3D%20r0%20vs%20r0%2B1%22%5D%0A%20%20TR%20--%3E%20R%5B%22%E9%80%89%E5%AE%9A%E7%A7%A9%20r%22%5D%0A%20%20ME%20--%3E%20R%0A%20%20R%20--%3E%20B%5B%22%E7%BA%A6%E6%9D%9F%E8%AF%86%E5%88%AB%20%CE%B2%22%5D%0A%20%20B%20--%3E%20S%5B%22r%20%E6%9D%A1%E4%BB%B7%E5%B7%AE%20%E2%86%92%20OU%20%2F%20%E4%BA%A4%E6%98%93%E8%A7%84%E5%88%99%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Johansen 在高斯 VECM 里用 \\(\\Pi=\\alpha\\beta&#39;\\) 的秩作为协整个数，用迹与最大特征值做似然比。</li><li>\\(\\beta\\) 只识别到空间；交易方向需要规范化或经济约束，特征向量默认基没有「第一对」的含义。</li><li>确定性项与滞后改变临界值与尺寸；价差交易通常把常数放进协整方程，避免价差带漂移。</li><li>\\(p\\) 大、\\(T\\) 短、跳跃与断裂时，秩估计不可靠；先降维或分割样本。</li><li>秩通过后仍要对每条残差问半衰期、成本与样本外稳定性。</li><li>出处：Johansen, <em>Journal of Economic Dynamics and Control</em>, 1988；<em>Econometrica</em>, 1991；专著 <em>Likelihood-Based Inference in Cointegrated Vector Autoregressive Models</em>, 1995。</li></ul>',2))])}const f=o(_,[["render",d]]);export{g as __pageData,f as default};
